static int cmpChar(const void *a, const void *b) {
  return *(char *)a - *(char *)b;
}

char ***groupAnagrams(char **strs, int strsSize, int *returnSize, int **returnColumnSizes) {
  char ***res = (char ***)malloc(sizeof(char **) * strsSize);
  *returnColumnSizes = (int *)malloc(sizeof(int) * strsSize);
  int *used = (int *)calloc(strsSize, sizeof(int));
  *returnSize = 0;
  for (int i = 0; i < strsSize; i++) {
    if (used[i]) {
      continue;
    }
    char key[256];
    strcpy(key, strs[i]);
    qsort(key, strlen(key), 1, cmpChar);

    res[*returnSize] = (char **)malloc(sizeof(char *) * strsSize);
    int count = 0;
    for (int j = i; j < strsSize; j++) {
      if (used[j]) {
        continue;
      }
      char other[256];
      strcpy(other, strs[j]);
      qsort(other, strlen(other), 1, cmpChar);
      if (strcmp(key, other) == 0) {
        res[*returnSize][count++] = strs[j];
        used[j] = 1;
      }
    }
    (*returnColumnSizes)[*returnSize] = count;
    (*returnSize)++;
  }
  free(used);
  return res;
}

class Solution {
public:
  vector<vector<string>> groupAnagrams(vector<string> &strs) {
    unordered_map<string, vector<string>> groups;
    vector<string> order;
    for (const string &s : strs) {
      string key = s;
      sort(key.begin(), key.end());
      if (groups.find(key) == groups.end()) {
        order.push_back(key);
      }
      groups[key].push_back(s);
    }
    vector<vector<string>> res;
    for (const string &key : order) {
      res.push_back(groups[key]);
    }
    return res;
  }
};

func groupAnagrams(strs []string) [][]string {
	groups := map[string][]string{}
	var order []string
	for _, s := range strs {
		chars := strings.Split(s, "")
		sort.Strings(chars)
		key := strings.Join(chars, "")
		if _, ok := groups[key]; !ok {
			order = append(order, key)
		}
		groups[key] = append(groups[key], s)
	}
	res := make([][]string, 0, len(order))
	for _, key := range order {
		res = append(res, groups[key])
	}
	return res
}

class Solution {
  public List<List<String>> groupAnagrams(String[] strs) {
    Map<String, List<String>> groups = new LinkedHashMap<>();
    for (String s : strs) {
      char[] chars = s.toCharArray();
      Arrays.sort(chars);
      String key = new String(chars);
      groups.computeIfAbsent(key, k -> new ArrayList<>()).add(s);
    }
    return new ArrayList<>(groups.values());
  }
}

class Solution:
    def groupAnagrams(self, strs: List[str]) -> List[List[str]]:
        groups = {}
        order = []
        for s in strs:
            key = "".join(sorted(s))
            if key not in groups:
                groups[key] = []
                order.append(key)
            groups[key].append(s)
        return [groups[key] for key in order]

impl Solution {
  pub fn group_anagrams(strs: Vec<String>) -> Vec<Vec<String>> {
    let mut groups: HashMap<String, Vec<String>> = HashMap::new();
    let mut order: Vec<String> = vec![];
    for s in strs {
      let mut chars: Vec<char> = s.chars().collect();
      chars.sort();
      let key: String = chars.into_iter().collect();
      if !groups.contains_key(&key) {
        order.push(key.clone());
      }
      groups.entry(key).or_insert_with(Vec::new).push(s);
    }
    order
      .into_iter()
      .map(|key| groups.remove(&key).unwrap())
      .collect()
  }
}

const groupAnagrams = (strs: string[]): string[][] => {
  const groups = new Map<string, string[]>();
  const order: string[] = [];
  for (const s of strs) {
    const key = s.split('').sort().join('');
    if (!groups.has(key)) {
      groups.set(key, []);
      order.push(key);
    }
    groups.get(key)!.push(s);
  }
  return order.map((key) => groups.get(key)!);
};
